    private fun lesson009() = Lesson(
        id = "mit_6_004_2017_s009",
        title = "Arbitrer puissance, surface et vitesse",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.MathChallenge(id = "mit_6_004_2017_s009_e01", prompt = "Dans le modèle Pdyn∝CV²f, C et l’activité restent constants. V passe de 1 à 0,8 et f de 1 à 1,25. Quel est le rapport \$\\frac{P_{\\text{nouvelle}}}{P_{\\text{ancienne}}}\$ ?", options = listOf("5/4", "16/25", "4/5", "1"), correctOptionIndex = 2, explanation = "Le rapport vaut 0,8²×1,25 = (16/25)×(5/4) = 4/5. Ce calcul ne modélise ni les fuites ni la faisabilité temporelle.", hint = "La tension intervient au carré, la fréquence linéairement."),
            Exercise.MultipleChoice(id = "mit_6_004_2017_s009_e02", prompt = "Un additionneur carry-select calcule la partie haute pour retenue 0 et retenue 1. Pourquoi ?", options = listOf("Pour rendre la retenue toujours égale à zéro", "Pour sélectionner le bon résultat sans attendre de commencer le calcul haut", "Pour éliminer tout multiplexeur", "Pour doubler la largeur mathématique du résultat"), correctOptionIndex = 1, explanation = "Les deux hypothèses sont calculées avant l’arrivée de la retenue basse. Celle-ci commande ensuite le MUX ; on paie deux calculs hauts pour réduire l’attente.", hint = "Sépare le temps de calcul des hypothèses du temps de sélection."),
            Exercise.MathChallenge(id = "mit_6_004_2017_s009_e03", prompt = "Un multiplicateur réutilisé prend huit cycles de 2 ns par produit et ne commence pas le suivant avant de finir. Quel intervalle minimal entre produits, en ns ?", options = listOf("16", "2", "4", "8"), correctOptionIndex = 0, explanation = "Sans recouvrement ni duplication, chaque produit occupe la ressource pendant 8×2=16 ns. Le débit est un produit par 16 ns.", hint = "Vérifie si les opérations peuvent se chevaucher avant d’utiliser un débit de pipeline.")
        ),
        objective = "Comparer des architectures arithmétiques et calculer l’effet d’une modification de tension ou de fréquence.",
        learningNotes = "Une optimisation n’a de sens qu’avec un objectif et des contraintes. Dupliquer un calcul réduit parfois la latence, mais augmente surface et consommation. Dans le modèle dynamique simplifié, la puissance est proportionnelle à l’activité, à la capacité commutée, à V² et à la fréquence. Réduire la tension de moitié divise donc ce terme par quatre si tout le reste est maintenu. Les limites de timing et les fuites restent à examiner. Un additionneur à propagation de retenue attend une chaîne de retenues. Un carry-select calcule en parallèle deux résultats possibles puis choisit selon la retenue reçue : il échange du matériel contre du temps. Un multiplicateur séquentiel réutilise des composants, économisant la surface au prix de plusieurs cycles.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/calendar/", "https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/c8/c8s1/"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 9,
        sourceTitle = "Unit 8: Design tradeoffs: power, speed, area, throughput",
        sessionKind = "lesson"
    )

    private fun lesson010() = Lesson(
        id = "mit_6_004_2017_s010",
        title = "Lire le jeu d’instructions du Beta",
