        isLocked = false,
        exercises = listOf(
            Exercise.MathChallenge(id = "mit_6_004_2017_s010_e01", prompt = "Une branche Beta est à l’adresse octet 100 et son déplacement signé est −3. Si elle est prise, quelle adresse octet devient le PC ?", options = listOf("104", "92", "88", "97"), correctOptionIndex = 1, explanation = "La cible est PC+4+4×déplacement =100+4−12=92. Le déplacement est relatif à l’instruction suivante.", hint = "Le littéral de branche est un déplacement en mots de quatre octets."),
            Exercise.MathChallenge(id = "mit_6_004_2017_s010_e02", prompt = "Quel résultat 32 bits obtient ADDC(R31,−7,R2) ?", options = listOf("0xFFFFFFF9", "0x0000FFF9", "0x00000007", "0xFFFFFFF8"), correctOptionIndex = 0, explanation = "R31 fournit zéro ; −7 est prolongé avec son signe et représenté modulo 2^32 : 0xFFFFFFF9.", hint = "Complémente 7 sur 32 bits puis ajoute un."),
            Exercise.MultipleChoice(id = "mit_6_004_2017_s010_e03", prompt = "Pourquoi cinq bits suffisent-ils pour désigner un registre du Beta ?", options = listOf("Chaque registre ne contient que cinq bits", "Le PC ne possède que cinq bits", "Le Beta possède seulement cinq registres", "Ils distinguent exactement 32 indices de registre"), correctOptionIndex = 3, explanation = "Un champ de cinq bits fournit 2^5=32 valeurs. La largeur de sélection est différente de la largeur de 32 bits de chaque registre.", hint = "Compte les possibilités du champ, pas les bits de la donnée."),
            Exercise.MathChallenge(id = "mit_6_004_2017_s010_e04", prompt = "Le tableau de mots commence à l’adresse octet 200. Quelle est l’adresse de son élément d’indice 6, avec indices commençant à zéro ?", options = listOf("220", "248", "224", "206"), correctOptionIndex = 2, explanation = "Chaque mot occupe quatre octets ; l’adresse est 200+4×6=224.", hint = "Convertis l’indice de mot en déplacement en octets.")
        ),
        objective = "Interpréter les registres, les constantes signées, les adresses et les branches du Beta.",
        learningNotes = "L’architecture à programme enregistré place instructions et données dans la mémoire. Le Beta utilise des instructions de 32 bits, trente-deux registres de 32 bits et des adresses exprimées en octets. Ses accès ordinaires portent sur des mots de quatre octets. R31 se lit toujours comme zéro et ignore les écritures. Le format à constante contient un littéral signé de seize bits, prolongé avec son signe. Les opérations arithmétiques conservent les trente-deux bits de poids faible. Une branche relative calcule sa cible depuis PC+4, en multipliant le déplacement signé par quatre. Ainsi, depuis PC=100 avec déplacement −3, la cible est 104−12=92. Bien séparer adresse en octets et déplacement en mots évite une erreur fréquente.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/calendar/", "https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/c9/c9s1/"),
