            Exercise.MathChallenge(id = "mit_6_004_2017_s011_e02", prompt = "Une macro UASM produit deux instructions Beta de quatre octets chacune. Une étiquette est placée immédiatement après, la première instruction étant à 80. Quelle est la valeur de l’étiquette ?", options = listOf("82", "84", "96", "88"), correctOptionIndex = 3, explanation = "L’assemblage émet huit octets aux adresses 80 à 87. L’étiquette suivante vaut donc 88.", hint = "Une macro peut produire plusieurs instructions ; compte les octets effectivement émis."),
