            Exercise.MultipleChoice(id = "mit_6_004_2017_s012_e02", prompt = "Dans t=a+b ; a=a+1 ; u=a+b, peut-on remplacer la dernière somme par l’ancienne valeur t pour tous les entiers sans débordement ?", options = listOf("Oui, si b est dans un registre", "Oui, toute addition est indépendante des écritures", "Non, a a été modifié entre les deux sommes", "Oui, les deux textes a+b sont identiques"), correctOptionIndex = 2, explanation = "La dernière somme vaut l’ancienne somme plus un. L’identité syntaxique ne suffit pas : il faut vérifier les définitions des opérandes.", hint = "Suis la valeur de a au moment de chaque calcul."),
            Exercise.MathChallenge(id = "mit_6_004_2017_s012_e03", prompt = "Pour charger A[i], A commence à l’adresse 1000 et i=9, les mots font quatre octets. Quelle adresse effective faut-il calculer ?", options = listOf("1040", "1036", "1009", "1032"), correctOptionIndex = 1, explanation = "Le compilateur calcule base+taille×indice =1000+4×9=1036.", hint = "Le type de l’élément détermine l’échelle de l’indice.")
        ),
        objective = "Traduire une expression et reconnaître les conditions de validité d’une optimisation.",
        learningNotes = "Compiler consiste à préserver le comportement d’un programme en le traduisant en opérations plus élémentaires. Une expression composée se décompose en chargements, calculs intermédiaires et écriture du résultat. Un tableau de mots exige une multiplication de l’indice par quatre avant le chargement. Une condition devient une comparaison suivie d’une branche. Une boucle ajoute un retour vers son test. Le compilateur peut conserver des valeurs dans les registres, propager des constantes et supprimer des calculs redondants. La transformation doit toutefois respecter les dépendances : réutiliser a+b n’est correct que si ni a ni b n’a changé entre les deux évaluations. Une opération sans effet observable peut être retirée, mais une écriture ou un accès matériel ne se traite pas comme une simple expression pure.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/calendar/", "https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/c11/c11s1/"),
