            Exercise.MultipleChoice(id = "mit_6_004_2017_s013_e02", prompt = "Pourquoi une procédure récursive doit-elle préserver son adresse de retour avant d’appeler à nouveau une procédure avec le même registre de liaison ?", options = listOf("Le matériel copie automatiquement tous les cadres en mémoire", "Le nouvel appel écrase le registre de liaison", "L’adresse de retour est toujours constante", "Le registre de liaison ne peut pas contenir une adresse"), correctOptionIndex = 1, explanation = "L’appel interne y place sa propre adresse de reprise. Il faut sauver puis restaurer l’adresse de l’appel externe, généralement dans le cadre de pile.", hint = "Compare les deux adresses de reprise de deux appels actifs."),
            Exercise.MathChallenge(id = "mit_6_004_2017_s013_e03", prompt = "fact(n) appelle fact(n−1) jusqu’à fact(0), sans optimisation de récursion. Combien de cadres de fact sont simultanément actifs au maximum pour fact(5) ?", options = listOf("6", "4", "5", "120"), correctOptionIndex = 0, explanation = "Les appels fact(5), fact(4), fact(3), fact(2), fact(1), fact(0) restent tous actifs avant le premier retour : six cadres.", hint = "Compte le cas de base dans la profondeur maximale.")
        ),
        objective = "Suivre la convention de pile Beta et préserver l’état nécessaire aux appels imbriqués.",
        learningNotes = "Un appel doit mémoriser où reprendre et conserver les valeurs dont l’appelant aura encore besoin. Un registre de retour unique ne suffit pas pour la récursion : chaque nouvel appel écraserait l’adresse précédente. Les activations ont donc chacune un cadre de pile. Dans la convention décrite pour le Beta, la pile croît vers les adresses hautes et SP désigne le premier mot libre. PUSH réserve quatre octets, puis écrit le mot à SP−4. POP restaure la valeur et libère cet espace. Les cadres sont dépilés dans l’ordre inverse des appels. Le pointeur de base fournit des positions stables pour les arguments et les variables locales. Respecter la convention permet à des procédures compilées séparément de coopérer.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/calendar/", "https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/c12/c12s1/"),
