            Exercise.MathChallenge(id = "mit_6_004_2017_s014_e04", prompt = "Une ROM de contrôle est indexée par les six bits d’opcode et produit douze bits de commande. Combien de bits de données contient-elle ?", options = listOf("384", "4096", "768", "72"), correctOptionIndex = 2, explanation = "Il existe 64 opcodes possibles et douze sorties par entrée : 64×12=768 bits, hors logique de sélection.", hint = "L’opcode détermine le nombre de lignes de la ROM.")
