            Exercise.MathChallenge(id = "mit_6_004_2017_s015_e04", prompt = "Un compteur d’état fait q←(q+1) modulo 4 à chaque front, depuis q=0. Quelle valeur après sept fronts ?", options = listOf("2", "3", "0", "1"), correctOptionIndex = 1, explanation = "La séquence est 1,2,3,0,1,2,3 ; le calcul équivalent est 7 modulo 4.", hint = "Repère la période de la machine.")
