    private fun lesson016() = Lesson(
        id = "mit_6_004_2017_s016",
        title = "Exploiter la localité avec un cache",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.MathChallenge(id = "mit_6_004_2017_s016_e01", prompt = "Un cache direct de 64 lignes possède des blocs de 16 octets et des adresses de 32 bits. Combien de bits de tag faut-il ?", options = listOf("20", "24", "26", "22"), correctOptionIndex = 3, explanation = "Le déplacement occupe log₂16=4 bits et l’indice log₂64=6 bits. Il reste 32−4−6=22 bits de tag.", hint = "Sépare déplacement dans le bloc, indice de ligne et tag."),
            Exercise.MathChallenge(id = "mit_6_004_2017_s016_e02", prompt = "Un accès cache coûte 2 ns ; 5 % des accès ajoutent une pénalité de défaut de 40 ns. Quel temps moyen, en ns ?", options = listOf("40", "42", "4", "2"), correctOptionIndex = 2, explanation = "Le coût de base est payé à chaque accès, puis 0,05×40=2 ns en moyenne s’ajoutent : 4 ns.", hint = "La pénalité est supplémentaire, pas le temps total d’un défaut."),
            Exercise.MultipleChoice(id = "mit_6_004_2017_s016_e03", prompt = "Un programme parcourt les mots consécutifs d’un tableau et un bloc contient quatre mots. Quelle propriété rend ce transfert en bloc utile ?", options = listOf("La croissance de la pile", "La localité spatiale", "La métastabilité", "L’indécidabilité de l’arrêt"), correctOptionIndex = 1, explanation = "Après avoir demandé un mot, le programme demande probablement ses voisins. Les amener ensemble peut éviter des défauts ultérieurs.", hint = "Repère le lien entre proximité des adresses et utilisation future."),
            Exercise.MathChallenge(id = "mit_6_004_2017_s016_e04", prompt = "Un cache direct de huit lignes contient un mot de quatre octets par ligne. Quel indice de ligne utilise l’adresse octet 0xAC ?", options = listOf("3", "4", "5", "7"), correctOptionIndex = 0, explanation = "0xAC=172. Le numéro de mot est 172/4=43 et son indice est 43 modulo 8 =3.", hint = "Retire les deux bits de déplacement octet avant de prendre l’indice.")
        ),
        objective = "Décomposer une adresse et calculer le coût moyen d’une hiérarchie mémoire.",
        learningNotes = "La mémoire idéale serait à la fois rapide, grande et bon marché. La hiérarchie combine des technologies aux compromis différents. Le cache conserve des blocs récemment utilisés. La localité temporelle favorise leur réutilisation. La localité spatiale rend utile le transfert des mots voisins. Dans un cache direct, certains bits choisissent une ligne et le tag distingue les blocs qui partagent cette ligne. Un bit valide empêche de confondre un contenu initial indéfini avec une donnée présente. Pour des blocs de seize octets, quatre bits représentent le déplacement interne. Avec 64 lignes, six autres bits sélectionnent la ligne. Le temps moyen dépend du taux de défaut et de sa pénalité. Un petit nombre de défauts coûteux peut dominer le temps total.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/calendar/", "https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/c14/c14s1/"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 16,
        sourceTitle = "Unit 14: Multilevel memories: locality, performance, caches",
        sessionKind = "lesson"
    )

    private fun lesson017() = Lesson(
        id = "mit_6_004_2017_s017",
        title = "Réduire les conflits et gérer les écritures",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.MathChallenge(id = "mit_6_004_2017_s017_e01", prompt = "Cache direct vide : deux lignes, un mot par bloc, lecture avec allocation. Pour la séquence de numéros de mots 0,2,0,2, combien de défauts ?", options = listOf("2", "3", "4", "1"), correctOptionIndex = 2, explanation = "Les mots 0 et 2 ciblent tous deux la ligne d’indice 0. Chaque accès remplace l’autre : quatre défauts.", hint = "Calcule numéro de mot modulo nombre de lignes à chaque accès."),
            Exercise.MathChallenge(id = "mit_6_004_2017_s017_e02", prompt = "Le même accès 0,2,0,2 utilise maintenant un cache vide de capacité deux mots, entièrement associatif, allocation en lecture. Combien de défauts ?", options = listOf("4", "2", "0", "1"), correctOptionIndex = 1, explanation = "Les deux premiers accès chargent les deux blocs ; ils coexistent et les deux suivants sont des succès.", hint = "Vérifie si les deux blocs peuvent rester présents simultanément."),
            Exercise.MultipleChoice(id = "mit_6_004_2017_s017_e03", prompt = "Dans un cache write-back, une ligne valide et dirty doit être évincée. Quelle action préserve les données ?", options = listOf("Écrire son contenu modifié en mémoire avant de réutiliser la ligne", "L’effacer immédiatement sans retour mémoire", "Effacer seulement son tag en gardant la mémoire inchangée", "Ignorer le dirty puisque le tag est valide"), correctOptionIndex = 0, explanation = "Dirty signifie que la mémoire ne possède pas la version la plus récente. Cette version doit être sauvegardée avant écrasement.", hint = "Le bit dirty décrit une divergence entre cache et mémoire.")
        ),
        objective = "Tracer des accès conflictuels et interpréter associativité, remplacement et bit dirty.",
        learningNotes = "Deux adresses différentes peuvent sélectionner la même ligne d’un cache direct. Si le programme alterne ces blocs, chaque accès évince le précédent malgré une capacité totale suffisante. Un cache associatif par ensembles offre plusieurs emplacements possibles dans le même ensemble. Il faut alors comparer plusieurs tags et choisir une victime. L’associativité réduit certains conflits sans supprimer les défauts de capacité ou les premiers chargements. Les écritures introduisent un autre compromis. En write-through, elles sont répercutées vers la mémoire. En write-back, la ligne modifiée porte un bit dirty et n’est recopiée qu’à son éviction. Une ligne propre peut être remplacée sans écriture de retour. Les politiques de défaut en écriture doivent aussi être précisées pour tracer correctement une séquence.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/calendar/", "https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/c14/c14s1/"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 17,
        sourceTitle = "Unit 14: Cache design issues (continued)",
        sessionKind = "lesson"
    )

    private fun lesson018() = Lesson(
        id = "mit_6_004_2017_s018",
        title = "Pipeliner le Beta malgré les dépendances",
