        exercises = listOf(
            Exercise.MathChallenge(id = "mit_6_004_2017_s018_e01", prompt = "Dans le pipeline `IF/RF/ALU/MEM/WB` du support, le LD est en IF au cycle 1. Son consommateur immédiat arrive en RF au cycle 3 et ne peut recevoir la donnée que lorsque LD est en WB, cycle 5. Combien de cycles RF faut-il bloquer ?", options = listOf("3", "2", "0", "1"), correctOptionIndex = 1, explanation = "Le consommateur doit attendre pendant les cycles 3 et 4 ; il peut utiliser le bypass WB au cycle 5. La réponse dépend explicitement de ce pipeline.", hint = "Compare le cycle de besoin initial au cycle de disponibilité."),
            Exercise.MathChallenge(id = "mit_6_004_2017_s018_e02", prompt = "Dans ce même pipeline, combien d’instructions indépendantes insérer entre un LD et son consommateur immédiat suffit à absorber ces deux attentes ?", options = listOf("2", "0", "1", "4"), correctOptionIndex = 0, explanation = "Chaque instruction indépendante retarde le consommateur d’un cycle ; deux décalent son RF du cycle 3 au cycle 5. Il faut préserver toutes les autres dépendances.", hint = "Décale le cycle RF du consommateur, sans retarder le producteur."),
            Exercise.MultipleChoice(id = "mit_6_004_2017_s018_e03", prompt = "ADDC écrit R2 et l’instruction suivante lit R2. Le résultat est déjà calculé mais pas encore écrit au fichier de registres. À quoi sert le bypass ?", options = listOf("Remplacer le résultat par l’ancienne valeur de R2", "Supprimer l’instruction productrice", "Rendre les dépendances mathématiquement inexistantes", "Acheminer le résultat récent vers l’entrée du consommateur"), correctOptionIndex = 3, explanation = "Le bypass conserve la dépendance mais fournit la bonne valeur avant son écriture normale. La logique doit choisir le producteur pertinent le plus récent.", hint = "Distingue disponibilité dans le chemin de données et présence dans le fichier de registres."),
            Exercise.MathChallenge(id = "mit_6_004_2017_s018_e04", prompt = "100 instructions traversent cinq étapes, une instruction lancée par cycle, avec huit cycles de blocage au total. Combien de cycles jusqu’à la fin, pipeline initialement vide ?", options = listOf("108", "500", "112", "100"), correctOptionIndex = 2, explanation = "Sans blocage il faut 100+5−1=104 cycles. Les huit attentes donnent 112 cycles.", hint = "Ajoute remplissage et blocages au flux idéal.")
        ),
        objective = "Tracer les cinq étapes et calculer les attentes de données dans le pipeline du support.",
        learningNotes = "Le Beta étudié répartit les instructions entre IF, RF, ALU, MEM et WB. Plusieurs instructions progressent ensemble, mais leurs dépendances restent celles de l’exécution séquentielle. Une instruction consommatrice ne peut utiliser une ancienne valeur simplement parce que l’écriture du producteur n’a pas encore atteint le fichier de registres. Le bypass renvoie une valeur déjà calculée vers l’étage qui en a besoin. Attention au modèle exact : dans le pipeline présenté, les opérandes sont requis en RF et la donnée d’un LD n’est disponible pour bypass qu’en WB. Un consommateur immédiatement après ce LD exige donc deux cycles d’attente, même avec bypass complet. Déplacer deux instructions indépendantes entre eux peut combler ces cycles sans modifier le résultat.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/calendar/", "https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/c15/c15s1/"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 18,
        sourceTitle = "Unit 15: Pipelining the Beta: pipeline diagrams, data hazards",
        sessionKind = "lesson"
    )

    private fun lesson019() = Lesson(
