            Exercise.MathChallenge(id = "mit_6_004_2017_s019_e01", prompt = "CPI de base 1, branches 20 % des instructions, 25 % des branches mal prédites, pénalité de deux cycles sans recouvrement. Quel CPI moyen ?", options = listOf("11/10", "5/4", "3/2", "2"), correctOptionIndex = 0, explanation = "Le surcoût est 0,20×0,25×2=0,10 ; le CPI total vaut 1,10.", hint = "Applique le taux de mauvaise prédiction seulement aux branches."),
            Exercise.MultipleChoice(id = "mit_6_004_2017_s019_e02", prompt = "Un ST du mauvais chemin est encore dans le pipeline lorsqu’une branche mal prédite est résolue, avant son écriture mémoire. Que faut-il faire ?", options = listOf("Laisser écrire puis changer seulement le PC", "Écrire dans R31 pour annuler rétroactivement la mémoire", "Attendre que la mémoire retrouve seule son état", "Annuler son autorisation d’écriture mémoire"), correctOptionIndex = 3, explanation = "Un stockage est un effet observable. Le contrôle doit empêcher qu’une instruction annulée écrive, sinon changer le PC ne restaure pas la mémoire.", hint = "Repère l’effet de bord irréversible dans le chemin de données."),
            Exercise.MultipleChoice(id = "mit_6_004_2017_s019_e03", prompt = "Deux variantes ont CPI×période : A = 1,2×2 ns et B = 1,5×1,5 ns. Pour le même nombre d’instructions, quelle variante termine plus vite ?", options = listOf("A et B sont égales", "B, avec 1 ns par instruction", "B, avec 2,25 ns par instruction en moyenne", "A, avec 2 ns par instruction"), correctOptionIndex = 2, explanation = "A demande 2,4 ns par instruction ; B demande 2,25 ns. La période plus courte de B compense ici son CPI plus élevé.", hint = "Multiplie le CPI par la durée du cycle pour chaque variante.")
        ),
        objective = "Quantifier une pénalité de branche et empêcher les instructions annulées de modifier l’état.",
        learningNotes = "Une dépendance de contrôle apparaît lorsque l’adresse suivante dépend d’une branche encore en cours de résolution. Prédire permet d’avancer, mais une mauvaise prédiction oblige à éliminer les instructions du mauvais chemin. Annuler seulement leur calcul ne suffit pas : leurs écritures en mémoire et dans les registres doivent être désactivées. Les exceptions introduisent également un changement de contrôle et une adresse de reprise à conserver selon la convention du processeur. La profondeur du pipeline réduit parfois la période tout en augmentant le nombre d’instructions spéculatives à annuler. L’évaluation doit donc comparer temps par instruction et taux d’aléas. Avec 20 % de branches, 25 % de mauvaises prédictions et une pénalité de deux cycles, le surcoût moyen vaut 0,1 cycle par instruction.",
