        sessionKind = "lesson"
    )

    private fun lesson020() = Lesson(
        id = "mit_6_004_2017_s020",
        title = "Traduire et protéger la mémoire virtuelle",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.MathChallenge(id = "mit_6_004_2017_s020_e01", prompt = "Pages de 4096 octets : l’adresse virtuelle 0x2345 est dans une page traduite vers le cadre physique 9. Quelle adresse physique obtient-on ?", options = listOf("0x9234", "0x9002", "0x2349", "0x9345"), correctOptionIndex = 3, explanation = "Le déplacement 0x345 est conservé. Le cadre 9 fournit la base 9×0x1000 ; l’adresse finale vaut 0x9345.", hint = "Sépare les douze bits bas du numéro de page."),
            Exercise.MathChallenge(id = "mit_6_004_2017_s020_e02", prompt = "Adresses virtuelles de 32 bits, pages de 4096 octets, table plate avec une entrée de quatre octets par page. Quelle taille de table en octets ?", options = listOf("1048576", "16777216", "4194304", "4096"), correctOptionIndex = 2, explanation = "Le nombre de pages est 2^(32−12)=2^20 ; quatre octets par entrée donnent 2^22=4194304 octets.", hint = "Compte toutes les pages de l’espace virtuel, pas seulement les pages résidentes."),
            Exercise.MultipleChoice(id = "mit_6_004_2017_s020_e03", prompt = "Un accès manque dans le TLB, mais son entrée de table indique une page présente en mémoire physique. Faut-il nécessairement lire le disque ?", options = listOf("Non, mais les permissions deviennent inutiles", "Non, il suffit de retrouver et mémoriser la traduction autorisée", "Oui, tout défaut de TLB est un défaut de page", "Oui, la page physique n’existe plus"), correctOptionIndex = 1, explanation = "Le TLB est un cache de traductions. Son absence ne signifie pas que la page manque en mémoire ; les permissions doivent toujours être vérifiées.", hint = "Distingue absence du cache de traduction et absence de la donnée en mémoire."),
            Exercise.MathChallenge(id = "mit_6_004_2017_s020_e04", prompt = "Avec 4 KiB par page, quel est le numéro de page virtuelle de l’adresse décimale 20000 ?", options = listOf("4", "3", "5", "3616"), correctOptionIndex = 0, explanation = "20000=4×4096+3616. Le numéro de page est quatre et le déplacement est 3616 octets.", hint = "Utilise le quotient entier pour le numéro de page.")
        ),
        objective = "Décomposer une adresse en page et déplacement, puis distinguer défaut de TLB et défaut de page.",
        learningNotes = "La mémoire virtuelle interpose une traduction entre les adresses du programme et celles de la mémoire physique. Pour une page de 4096 octets, les douze bits bas représentent le déplacement et restent inchangés. La table remplace le numéro de page virtuelle par un numéro physique. Une adresse 0x2345 appartient à la page virtuelle 2 avec déplacement 0x345. Si cette page est placée dans le cadre physique 9, l’adresse devient 0x9345. Le TLB mémorise des traductions récentes pour éviter de relire la table à chaque accès. Un défaut de TLB peut être résolu avec une page déjà résidente. Un défaut de page requiert une prise en charge par le système. Les permissions de la traduction contrôlent aussi les accès autorisés.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/calendar/", "https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/c16/c16s1/"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 20,
        sourceTitle = "Unit 16: Virtual memory: mapping, protection, contexts",
        sessionKind = "lesson"
    )

