        isLocked = false,
        exercises = listOf(
            Exercise.MathChallenge(id = "mit_6_004_2017_s023_e01", prompt = "Une requête doit être entièrement traitée au plus 80 µs après son arrivée. Le service prend 30 µs. Quelle latence maximale avant de commencer, en µs ?", options = listOf("50", "30", "80", "110"), correctOptionIndex = 0, explanation = "La contrainte est L+30≤80, donc L≤50 µs. Le début du service n’est pas sa fin.", hint = "Soustrais le temps de service à l’échéance totale."),
            Exercise.MathChallenge(id = "mit_6_004_2017_s023_e02", prompt = "Un périphérique interrompt 200 fois par seconde et chaque service occupe 100 µs de CPU. Quelle fraction du temps CPU consomme-t-il, hors autres coûts ?", options = listOf("1/5", "1/2", "2", "1/50"), correctOptionIndex = 3, explanation = "200×100 µs=20000 µs par seconde, soit 0,02=1/50. Ce taux moyen ne garantit pas à lui seul les échéances.", hint = "Convertis les microsecondes en secondes avant de faire le rapport."),
            Exercise.MultipleChoice(id = "mit_6_004_2017_s023_e03", prompt = "Un processus attend une touche et aucun caractère n’est disponible. Quelle stratégie permet au CPU de faire un autre travail ?", options = listOf("Désactiver définitivement toutes les interruptions", "Relire plus vite une valeur inchangée", "Bloquer ce processus et le réveiller lorsque des données arrivent", "Boucler dans le processus sans jamais l’ordonner ailleurs"), correctOptionIndex = 2, explanation = "Le noyau peut marquer le processus en attente et exécuter un autre processus. L’interruption du périphérique fournit l’occasion de réveiller le lecteur.", hint = "Distingue absence de données pour un processus et absence de travail dans tout le système."),
            Exercise.MathChallenge(id = "mit_6_004_2017_s023_e04", prompt = "Deux services périodiques non recouvrables prennent respectivement 2 ms toutes les 10 ms et 3 ms toutes les 20 ms. Quelle utilisation moyenne totale du CPU ?", options = listOf("3/5", "7/20", "1/4", "1/2"), correctOptionIndex = 1, explanation = "La charge vaut 2/10+3/20=4/20+3/20=7/20. Être sous 1 est nécessaire, mais ne suffit pas à prouver toute politique d’ordonnancement correcte.", hint = "Additionne les fractions de service par période.")
        ),
        objective = "Comparer attente active et interruptions et vérifier une contrainte simple de temps réel.",
        learningNotes = "Un périphérique produit des événements à son rythme, indépendamment des instructions utilisateur. Un gestionnaire d’interruption peut capturer les données dans un tampon du noyau. Un appel système les remet ensuite au programme demandeur. Cette séparation évite que chaque programme surveille continuellement le matériel. Attendre une donnée peut suspendre le processus pour laisser tourner un autre travail, plutôt que gaspiller le CPU dans une boucle. Pour une contrainte temps réel, la rapidité moyenne ne suffit pas : latence d’interruption et durée de service doivent respecter l’échéance dans le pire cas. Si un événement doit être terminé en 80 µs et nécessite 30 µs de service, il reste au plus 50 µs avant le début du gestionnaire. Les sections non interruptibles et les priorités influencent cette borne.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/calendar/", "https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/c18/c18s1/"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 23,
        sourceTitle = "Unit 18: Devices and interrupts; real-time",
        sessionKind = "lesson"
    )

    private fun lesson024() = Lesson(
        id = "mit_6_004_2017_s024",
        title = "Synchroniser les processus sans interblocage",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.MultipleChoice(id = "mit_6_004_2017_s024_e01", prompt = "Un tampon borné vide a une capacité de huit éléments. Quelles valeurs initiales pour les sémaphores placesLibres et élémentsDisponibles ?", options = listOf("placesLibres=0, élémentsDisponibles=8", "placesLibres=8, élémentsDisponibles=8", "placesLibres=1, élémentsDisponibles=1", "placesLibres=8, élémentsDisponibles=0"), correctOptionIndex = 3, explanation = "Toutes les places sont libres et aucun élément n’existe encore. Chaque production consomme une place et signale un élément ; chaque consommation fait l’inverse.", hint = "Compte séparément capacité restante et données présentes."),
            Exercise.MathChallenge(id = "mit_6_004_2017_s024_e02", prompt = "x=0. P lit x dans p ; Q lit x dans q ; P écrit p+1 dans x ; Q écrit q+1 dans x. Quelle valeur finale obtient-on ?", options = listOf("2", "4", "1", "0"), correctOptionIndex = 2, explanation = "Les deux lectures voient zéro. Chaque écriture pose donc un ; la deuxième écrase le même résultat. L’incrément complet n’était pas atomique.", hint = "Trace les valeurs locales p et q, pas seulement la variable partagée."),
            Exercise.MultipleChoice(id = "mit_6_004_2017_s024_e03", prompt = "Deux processus doivent acquérir les verrous A et B. Quelle règle évite leur interblocage par acquisition croisée ?", options = listOf("Ne jamais libérer A", "Tous acquièrent A avant B puis libèrent correctement les deux", "L’un acquiert A puis B, l’autre B puis A", "Chacun conserve son premier verrou en attendant indéfiniment l’autre"), correctOptionIndex = 1, explanation = "Un ordre global commun empêche un cycle où un processus attend A en détenant B et l’autre attend B en détenant A. Cela ne prouve pas automatiquement l’absence de famine.", hint = "Cherche à rendre impossible le cycle d’attente."),
            Exercise.MultipleChoice(id = "mit_6_004_2017_s024_e04", prompt = "Un sémaphore vaut 2. Deux WAIT réussissent, puis un troisième WAIT arrive avant tout SIGNAL. Quel est son comportement selon la convention non négative du cours ?", options = listOf("Il attend, la valeur restant 0", "Il réussit et la valeur devient −1", "Il réussit et la valeur devient 1", "Il détruit le sémaphore"), correctOptionIndex = 0, explanation = "Les deux premiers WAIT consomment les deux permissions. Le troisième ne peut décrémenter zéro ; il attend un SIGNAL.", hint = "Le support interdit les valeurs négatives pour ce modèle de sémaphore.")
        ),
        objective = "Déterminer les valeurs initiales des sémaphores et raisonner sur atomicité et ordre de verrouillage.",
        learningNotes = "La concurrence rend les entrelacements observables. Deux processus qui lisent chacun un compteur à zéro puis écrivent chacun un perdent une incrémentation. Une section critique doit rendre cette mise à jour indivisible vis-à-vis des autres processus. Le sémaphore du support est non négatif : WAIT attend une valeur positive puis la décrémente atomiquement. SIGNAL l’incrémente. Pour un tampon de capacité N, un sémaphore compte N places libres et un autre zéro élément disponible au départ. Un verrou supplémentaire protège les structures partagées lorsque plusieurs producteurs ou consommateurs peuvent agir. L’ordre des acquisitions compte : deux processus possédant chacun un verrou et attendant celui de l’autre peuvent rester bloqués. Imposer un ordre global des ressources supprime ce cycle d’attente.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/calendar/", "https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/c19/c19s1/"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 24,
        sourceTitle = "Unit 19: Communicating processes: semaphores, synchronization, atomicity, deadlock",
        sessionKind = "lesson"
    )

    private fun lesson025() = Lesson(
        id = "mit_6_004_2017_s025",
        title = "Relier les composants et transporter les messages",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.MathChallenge(id = "mit_6_004_2017_s025_e01", prompt = "Huit composants sont reliés par un lien bidirectionnel distinct pour chaque paire, sans boucle vers soi-même. Combien de liens ?", options = listOf("16", "56", "28", "8"), correctOptionIndex = 2, explanation = "Il existe 8×7 paires orientées, mais chaque lien sert les deux sens : 8×7/2=28.", hint = "Chaque paire de composants compte une seule fois."),
            Exercise.MathChallenge(id = "mit_6_004_2017_s025_e02", prompt = "Un message de 12000 bits emprunte un lien de débit 1000000000 \$\\frac{\\mathrm{bits}}{\\mathrm{s}}\$. Quelle durée minimale de sérialisation, en µs, hors en-têtes et propagation ?", options = listOf("12000", "12", "1,2", "120"), correctOptionIndex = 1, explanation = "12000/10^9 seconde =12×10^−6 seconde, donc 12 µs. Les délais physiques et d’attente s’ajoutent.", hint = "Divise la longueur en bits par le débit en bits par seconde."),
            Exercise.MathChallenge(id = "mit_6_004_2017_s025_e03", prompt = "Sur une grille 4×4, seuls les voisins horizontaux et verticaux sont directement reliés. Combien de sauts au minimum entre les deux coins opposés ?", options = listOf("6", "3", "4", "8"), correctOptionIndex = 0, explanation = "Il faut trois déplacements horizontaux et trois verticaux. La distance minimale est donc six sauts.", hint = "Additionne les déplacements nécessaires dans les deux dimensions.")
        ),
        objective = "Comparer coûts de topologie et distinguer latence de propagation et sérialisation.",
        learningNotes = "Les interfaces permettent à des composants de générations différentes de coopérer, mais les fils ont des contraintes physiques. Un bus partagé limite les communications simultanées et impose des précautions de commande électrique. Les liens série point à point et différentiels peuvent améliorer vitesse et robustesse. Une architecture complète doit encore décider comment router les messages. Un graphe complet de N composants comporte N(N−1)/2 liens bidirectionnels : le coût augmente quadratiquement. Une grille limite le nombre de voisins mais oblige certains messages à plusieurs sauts. Le temps de communication comprend aussi la sérialisation : envoyer 8000 bits sur un lien à un milliard de bits par seconde demande huit microsecondes, avant propagation et files d’attente. Les couches supérieures peuvent assurer la fiabilité au-dessus d’un transport élémentaire imparfait.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/calendar/", "https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/c20/c20s1/"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 25,
        sourceTitle = "Unit 20: System-level communication",
        sessionKind = "lesson"
    )

    private fun lesson026() = Lesson(
        id = "mit_6_004_2017_s026",
        title = "Mesurer les limites du parallélisme",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.MathChallenge(id = "mit_6_004_2017_s026_e01", prompt = "80 % du temps initial sont accélérés par quatre, le reste est inchangé. Quel gain global exact ?", options = listOf("8/5", "5/2", "4", "5"), correctOptionIndex = 1, explanation = "Le nouveau temps relatif vaut 1/5+(4/5)/4=2/5 ; le gain est son inverse, 5/2.", hint = "Pondère les temps, puis prends le rapport \$\\frac{\\text{ancien}}{\\text{nouveau}}\$."),
            Exercise.MathChallenge(id = "mit_6_004_2017_s026_e02", prompt = "Si 10 % du travail restent strictement séquentiels, quel gain maximal théorique quand le reste devient instantané ?", options = listOf("10", "9", "100", "Illimité"), correctOptionIndex = 0, explanation = "Le temps ne peut descendre sous 0,1 du temps initial ; le gain ne peut dépasser 1/0,1=10.", hint = "Fais tendre uniquement le temps de la partie parallélisable vers zéro."),
            Exercise.MultipleChoice(id = "mit_6_004_2017_s026_e03", prompt = "Dans le protocole MESI présenté, une ligne est partagée entre plusieurs caches et un cœur veut la modifier. Quelle action est nécessaire avant l’écriture locale exclusive ?", options = listOf("Laisser les autres copies valides et périmées", "Effacer le programme des autres cœurs", "Transformer toutes les lignes en constantes", "Invalider les copies partagées des autres caches"), correctOptionIndex = 3, explanation = "L’invalidation empêche les autres cœurs de réutiliser une ancienne valeur. Ils demanderont une version récente lors d’un accès ultérieur.", hint = "Une écriture exclusive ne doit pas coexister avec une copie valide ancienne."),
            Exercise.MultipleChoice(id = "mit_6_004_2017_s026_e04", prompt = "Sous cohérence séquentielle, x=y=0. P exécute x=1 puis r=y ; Q exécute y=1 puis s=x. Le résultat r=s=0 est-il possible ?", options = listOf("Oui, sous tout ordre mémoire imaginable", "Non, car chaque lecture doit obligatoirement valoir 2", "Non, aucun entrelacement global ne respecte les deux ordres et ce résultat", "Oui, si les deux écritures sont avant les deux lectures"), correctOptionIndex = 2, explanation = "r=0 impose lecture r avant écriture y ; s=0 impose lecture s avant écriture x. Avec les ordres x→r et y→s, cela créerait un cycle impossible dans un ordre total. Cette réponse suppose la cohérence séquentielle.", hint = "Combine les deux ordres locaux avec les contraintes imposées par les lectures de zéro.")
        ),
        objective = "Appliquer Amdahl et distinguer cohérence des caches et ordre global des opérations.",
        learningNotes = "Le parallélisme peut concerner plusieurs instructions, plusieurs données d’une même opération ou plusieurs fils d’exécution. Il reste limité par les dépendances et les parties séquentielles. Si 80 % d’un calcul sont accélérés par quatre, le temps normalisé devient 0,2+0,8/4=0,4. Le gain total est seulement 2,5. Même une accélération infinie de cette partie ne dépasserait pas cinq. Les cœurs ont souvent leurs propres caches : une écriture doit alors rendre les copies anciennes inutilisables ou les mettre à jour. Le protocole MESI du support invalide notamment les autres copies avant une écriture exclusive. La cohérence d’une adresse ne suffit toutefois pas à définir tout l’ordre des opérations sur plusieurs adresses. Les garanties mémoire et les barrières doivent être examinées séparément.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/calendar/", "https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/c21/c21s1/"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 26,
        sourceTitle = "Unit 21: Parallel processing: performance limits, data- and thread-level parallelism",
        sessionKind = "lesson"
    )

    private fun lesson027() = Lesson(
        id = "mit_6_004_2017_s027",
        title = "Choisir une meilleure réalisation du Beta",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.MultipleChoice(id = "mit_6_004_2017_s027_e01", prompt = "Même programme : la variante A prend 1000 cycles à 2 ns, B prend 1400 cycles à 1,5 ns. Quelle variante est la plus rapide ?", options = listOf("A : 2000 ns contre 2100 ns pour B", "B : 1500 ns contre 2000 ns pour A", "A et B : 2000 ns chacune", "B : 1400 ns contre 2000 ns pour A"), correctOptionIndex = 0, explanation = "A prend 1000×2=2000 ns. B prend 1400×1,5=2100 ns. Une fréquence plus haute n’implique pas ici un programme plus rapide.", hint = "Compare les durées totales, pas seulement les périodes."),
            Exercise.MathChallenge(id = "mit_6_004_2017_s027_e02", prompt = "Une optimisation accélère par deux une partie qui occupait un quart du temps. Quel gain global exact, sans autre coût ?", options = listOf("2", "4/3", "3/2", "8/7"), correctOptionIndex = 3, explanation = "Le temps relatif vaut 3/4+(1/4)/2=7/8. Le gain vaut donc 8/7.", hint = "La partie non modifiée conserve ses trois quarts du temps initial."),
            Exercise.MultipleChoice(id = "mit_6_004_2017_s027_e03", prompt = "Une optimisation de l’ALU réduit son délai, mais le chemin critique reste entièrement dans une autre unité et aucune autre propriété ne change. Quel effet garanti sur la période minimale du système ?", options = listOf("Elle devient nulle", "Elle augmente du délai économisé", "Aucune réduction garantie de la période", "Elle est nécessairement divisée par deux"), correctOptionIndex = 2, explanation = "La période reste bornée par le chemin critique inchangé. L’ALU peut être plus rapide sans que le système le soit.", hint = "Identifie le chemin qui fixe réellement l’horloge."),
            Exercise.MultipleChoice(id = "mit_6_004_2017_s027_e04", prompt = "Deux réalisations doivent respecter une surface maximale de 100 unités : A occupe 90 et prend 12 ns par tâche, B occupe 120 et prend 8 ns. Quel choix respecte le cahier des charges ?", options = listOf("Aucune, car toute latence non nulle est interdite", "A seulement, malgré sa latence plus élevée", "B seulement, car elle est plus rapide", "Les deux, car la surface n’influence jamais la validité"), correctOptionIndex = 1, explanation = "B viole la limite de surface. Une optimisation n’est admissible que si elle respecte d’abord toutes les contraintes obligatoires.", hint = "Sépare admissibilité et classement des performances.")
        ),
        objective = "Comparer des variantes sous contraintes sans confondre fréquence, correction et performance globale.",
        learningNotes = "Le calendrier réserve L24 aux conseils du projet « Building a Better Beta », sans fournir un chapitre annoté distinct. Cette leçon propose donc une synthèse originale fondée sur les unités de compromis, réalisation du Beta, pipeline et parallélisme. Elle ne prétend pas restituer un support L24 absent ni réaliser le projet de laboratoire. Une meilleure variante doit d’abord exécuter correctement le même jeu d’instructions, puis améliorer une mesure explicitée sous contraintes de surface et de puissance. Le temps d’exécution vaut nombre d’instructions × CPI × période. Réduire la période de 20 % tout en augmentant le CPI de 50 % peut ainsi ralentir le programme. Mesurer un ensemble représentatif et examiner les chemins critiques rend les choix de conception comparables.",
        sourceUrls = listOf("https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/calendar/", "https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/c8/c8s1/", "https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/c13/c13s1/", "https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/c15/c15s1/", "https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/c21/c21s1/"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 27,
        sourceTitle = "Building a Better Beta: tips for the design project",
        sessionKind = "lesson"
    )

    private fun lesson028() = Lesson(
        id = "mit_6_004_2017_s028",
        title = "Quiz 4 — entraînement sur l’organisation du système",
