            Exercise.MathChallenge(id = "mit_6_004_2017_s028_e02", prompt = "Une échéance est fixée à 120 µs après l’événement et le service dure 45 µs. Quelle latence maximale avant le service, en µs ?", options = listOf("120", "165", "75", "45"), correctOptionIndex = 2, explanation = "L+45≤120 implique L≤75 µs. Le délai d’attente et la durée de traitement se cumulent.", hint = "Le service doit finir avant l’échéance."),
            Exercise.MultipleChoice(id = "mit_6_004_2017_s028_e03", prompt = "P détient A et attend B ; Q détient B et attend A. Aucun autre acteur ne libère ces verrous et aucun timeout n’existe. Que décrit cet état ?", options = listOf("Une accélération par pipeline", "Un interblocage par attente circulaire", "Un simple succès de cache", "Une garantie d’équité"), correctOptionIndex = 1, explanation = "Chacun attend une libération que l’autre ne peut effectuer avant d’avancer ; aucun ne progresse dans les hypothèses données.", hint = "Dessine les attentes entre les deux détenteurs."),
            Exercise.MathChallenge(id = "mit_6_004_2017_s028_e04", prompt = "Un lien série de 2000000 \$\\frac{\\mathrm{bits}}{\\mathrm{s}}\$ doit émettre 4000 bits sans surcharge. Quel temps de sérialisation en millisecondes ?", options = listOf("2", "1/2", "4", "8"), correctOptionIndex = 0, explanation = "4000/2000000=0,002 s, donc 2 ms. Propagation et attente ne sont pas incluses.", hint = "Convertis la seconde en millisecondes après la division.")
        ),
        objective = "Relier traduction mémoire, interruptions, exclusion mutuelle et communication.",
        learningNotes = "Le dernier quiz du calendrier porte sur L18 à L22. Il n’y a pas d’examen final dans le syllabus. Cet entraînement original conserve ce périmètre sans prétendre reproduire les questions officielles ni les travaux de laboratoire. L’organisation du système repose sur des contrats qui se complètent : la traduction mémoire sépare les espaces d’adresses, les interruptions rendent le matériel réactif, les sémaphores ordonnent les accès et les interfaces transportent les données. Une correction locale ne garantit pas tout le système. Une mise à jour protégée peut encore participer à un interblocage. Une faible charge moyenne d’interruptions peut manquer une échéance. Un défaut de TLB ne signifie pas forcément un accès disque. Les corrections explicitent ces distinctions.",
